 const priorFocus=sameModal?captureFocus():null,priorIndex=sameModal?modalFocusables().indexOf(document.activeElement as HTMLElement):-1;
 const scroll=sameModal?previous?.scrollTop??0:0;
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${title}"><header class="modal-header"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2></div><div class="modal-header-actions">${languageControl('modal-language-select')}<button class="icon-btn close-modal" title="${tr('Schließen','Close')}">${icon('x')}</button></div></header>${body}</section></div>`;
 renderedModal=modal;setModalInert(true);$('.close-modal').onclick=closeModal;$('.modal-backdrop').onclick=e=>{if(e.target===$('.modal-backdrop'))closeModal();};refreshIcons($('#modal-root'));wireLanguageControls();
 if(!restoreFocus(priorFocus,$('#modal-root')))(priorIndex>=0?modalFocusables()[Math.min(priorIndex,modalFocusables().length-1)]:null)?.focus({preventScroll:true});
 if(!$('#modal-root').contains(document.activeElement))$('.close-modal').focus({preventScroll:true});
 $('.modal').scrollTop=scroll;
