function renderModal(){
 if(modal==='progression'){modalShell(tr('Deine Stadt hat große Pläne.','Your city has big plans.'),tr('AUFTRÄGE · AUSBAUSTUFEN · STADTZIEL','QUESTS · CITY LEVELS · CITY GOAL'),renderProgressionDialog(state,progressionTab),true);progressionBindings($('#modal-root'));
 } else if(modal==='camera'){modalShell(tr('Deine Stadt aus jedem Blickwinkel.','Your city from every angle.'),tr('KAMERA & BAUEN','CAMERA & BUILDING'),`<div class="camera-guide">${[['hand',tr('M · Bewegen','M · Pan'),tr('Wähle die Hand oder drücke M. Dann mit der linken Maustaste ziehen. Alternativ: mittlere Maustaste oder Alt + links.','Select the hand or press M, then drag with the left mouse button. You can also use the middle mouse button or Alt + left drag.')],['move',tr('W A S D · Navigieren','W A S D · Navigate'),tr('Bewege die Kamera über die Region. Die Pfeiltasten funktionieren ebenfalls.','Move the camera across the region. The arrow keys work too.')],['grid-2x2',tr('Zonen · Rechteck aufziehen','Zones · Drag a rectangle'),tr('Wohnen, Gewerbe und Industrie von einer Ecke zur anderen ziehen. Loslassen baut die markierte Fläche.','Drag residential, commercial, or industrial zones from one corner to the other. Release to build the selected area.')],['undo-2',tr('Rechtsklick / Esc · Bau abbrechen','Right-click / Esc · Cancel construction'),tr('Verwirf den aktuellen Entwurf und baue mit demselben Werkzeug weiter. Mit V oder Auswählen wechselst du zur Grundstücksauswahl.','Discard the current draft and keep building with the same tool. Press V or choose Select to inspect plots.')],['rotate-cw',tr('Rechts ziehen · Drehen','Right drag · Rotate'),tr('Ohne aktiven Bauentwurf die rechte Maustaste gedrückt halten und ziehen. Q und E drehen in festen Schritten.','Without an active construction draft, hold the right mouse button and drag. Q and E rotate in fixed steps.')],['zoom-in',tr('Mausrad · Zoomen','Mouse wheel · Zoom'),tr('Scrolle zum Vergrößern und Verkleinern. Die Minikarte bringt dich direkt an einen Ort.','Scroll to zoom in and out. Click the minimap to jump to a location.')],['globe',tr('Region · Überblick','Region · Overview'),tr('Die Weltkugel zeigt die ganze Region. Wirkt der Blickwinkel ungewohnt, setzt das Fadenkreuz die Kamera zurück und bringt dich zur Innenstadt.','The globe shows the entire region. If the viewing angle feels unfamiliar, the crosshair resets the camera and takes you downtown.')],['rotate-cw',tr('R · Gebäude drehen','R · Rotate buildings'),tr('Wähle ein großes Gebäude und drehe seine komplette Baufläche mit R.','Select a large building and press R to rotate its entire footprint.')],['car',tr('Selbst fahren','Drive a vehicle'),tr('Zeige auf ein Fahrzeug und klicke auf das Lenkrad. W/S beschleunigt und bremst, A/D lenkt; Esc steigt aus.','Point at a vehicle and click the steering wheel. W/S accelerate and brake, A/D steer, and Esc exits.')],['rotate-ccw',tr('Handbremse · Driften','Handbrake · Drift'),tr('Halte bei etwas Tempo die Leertaste und lenke. Beim Loslassen finden die Reifen wieder Halt.','At speed, hold Space and steer. Release it to let the tires regain grip.')],['lightbulb',tr('L · Stadtbeleuchtung','L · City lighting'),tr('Schalte Fenster und versorgte Straßenlaternen über die Glühbirne oder Taste L.','Toggle windows and powered streetlights using the lightbulb or the L key.')],['person-standing',tr('C · Bewohner greifen','C · Pick up residents'),tr('Greife eine Figur und hebe sie mit der Maus an. Sanft absetzen lässt sie weiterlaufen; ein kräftiger Wurf kann sie töten.','Pick up a resident and lift them with the mouse. Put them down gently to let them keep walking; a hard throw can kill them.')]].map(([ic,title,desc])=>`<article>${icon(ic)}<div><h3>${title}</h3><p>${desc}</p></div></article>`).join('')}</div><button id="camera-use-pan" class="button primary full">${icon('hand')} ${tr('Kamera jetzt bewegen','Move the camera now')}</button>`,true);$('#camera-use-pan').onclick=()=>{closeModal();selectTool('pan');$('#world').focus({preventScroll:true});};
 } else if(modal==='budget'){
 const s=state.stats;
 modalShell(tr('Ein guter Plan für morgen.','A good plan for tomorrow.'),tr('STADTHAUSHALT','CITY BUDGET'),`<div class="budget-overview"><div><small>${tr('Verfügbare Mittel','Available funds')}</small><strong>${euro(state.money)}</strong></div><span class="budget-balance ${s.balance<0?'negative':''}">${s.balance>=0?'+':''}${euro(s.balance)}<small>${tr('pro Monat','per month')}</small></span></div><div class="budget-columns"><div class="budget-card"><h3>${tr('Monatliche Bilanz','Monthly balance')}</h3><div><span>${tr('Steuern & Wirtschaft','Taxes & economy')}</span><b class="positive">+ ${euro(s.income)}</b></div><div><span>${tr('Betrieb & Stadtversorgung','Operations & city services')}</span><b>− ${euro(s.expenses)}</b></div><div class="total"><span>${tr('Überschuss','Surplus')}</span><b>${euro(s.balance)}</b></div></div><div class="budget-card"><h3>${tr('Steuersatz','Tax rate')}</h3><div class="slider-label"><span>${tr('Einwohner & Unternehmen','Residents & businesses')}</span><b id="tax-value">${fmt(state.tax)} %</b></div><input id="tax-slider" type="range" min="0" max="25" step="1" value="${state.tax}" aria-label="${tr('Steuersatz','Tax rate')}"/><p>${tr('Niedrige Steuern fördern Zuzug. Hohe Steuern erhöhen Einnahmen, senken aber die Zufriedenheit.','Low taxes attract new residents. High taxes increase revenue but reduce happiness.')}</p></div></div><h3 class="funding-title">${tr('Investiere in Lebensqualität','Invest in quality of life')}</h3><div class="funding-grid">${([['police','shield-check',tr('Polizei','Police')],['fire','flame',tr('Feuerwehr','Fire department')],['health','heart-pulse',tr('Gesundheit','Health')],['education','graduation-cap',tr('Bildung','Education')]] as const).map(([key,ic,label])=>`<div class="funding-item"><label for="funding-${key}">${icon(ic)} ${label}<b id="funding-${key}-value">${fmt(state.funding[key])} %</b></label><input type="range" id="funding-${key}" data-funding="${key}" min="0" max="150" step="10" value="${state.funding[key]}"/></div>`).join('')}</div><div class="loan-row"><div><strong>${tr('Stadtanleihe','Municipal loan')}</strong><small>${tr(`Offene Kredite: ${euro(state.loan)} · Zinsen im Monatsbudget`,`Outstanding loans: ${euro(state.loan)} · Interest included in the monthly budget`)}</small></div><button class="button secondary" id="repay-loan" ${state.loan<=0?'disabled':''}>${tr(`${euro(10000)} zurückzahlen`,`Repay ${euro(10000)}`)}</button><button class="button primary" id="take-loan">${tr(`${euro(10000)} aufnehmen`,`Borrow ${euro(10000)}`)}</button></div>`,true);
 $('#tax-slider').oninput=e=>{state.tax=Number((e.target as HTMLInputElement).value);$('#tax-value').textContent=`${fmt(state.tax)} %`;recalculate(state);clearDisasterUndo();renderStats();scheduleSave();};$('#tax-slider').onchange=()=>rerenderKeepingFocus('tax-slider');document.querySelectorAll<HTMLInputElement>('[data-funding]').forEach(el=>{el.oninput=()=>{const key=el.dataset.funding as keyof CityState['funding'];state.funding[key]=Number(el.value);$(`#funding-${key}-value`).textContent=`${fmt(Number(el.value))} %`;recalculate(state);clearDisasterUndo();renderStats();scheduleSave();};el.onchange=()=>rerenderKeepingFocus(el.id);});$('#take-loan').onclick=()=>{const r=takeLoan(state);if(r.ok)cityChanged();toast(r.message,r.ok?'good':'warning');renderStats();renderModal();};$('#repay-loan').onclick=()=>{const r=repayLoan(state);if(r.ok)cityChanged();toast(r.message,r.ok?'good':'warning');renderStats();renderModal();};
 } else if(modal==='reports'){
 const s=state.stats;modalShell(tr('So geht es deiner Stadt.','How your city is doing.'),tr('STADTBERICHT','CITY REPORT'),`<div class="report-grid">${[['users',tr('Einwohner','Residents'),fmt(s.population)],['briefcase-business',tr('Arbeitsplätze','Jobs'),fmt(s.jobs)],['smile',tr('Zufriedenheit','Happiness'),`${fmt(s.happiness)} %`],['leaf',tr('Umweltbelastung','Pollution'),`${fmt(s.pollution)} %`]].map(([ic,label,v])=>`<div class="report-metric">${icon(ic)}<small>${label}</small><strong>${v}</strong></div>`).join('')}</div><div class="chart-header"><h3>${tr('Bevölkerungsentwicklung','Population history')}</h3><span>${tr(`Die letzten ${fmt(Math.min(36,state.history.length))} Monate`,`The last ${fmt(Math.min(36,state.history.length))} months`)}</span></div><div class="population-chart">${historyChart()}</div><div class="service-grid">${[['zap',tr('Strom','Power'),s.powerDemand,s.powerSupply,tr('Einh.','units')],['droplets',tr('Wasser','Water'),s.waterDemand,s.waterSupply,tr('Einh.','units')]].map(([ic,label,demand,supply,unit])=>`<div class="service-capacity"><div>${icon(String(ic))}<b>${label}</b><span>${fmt(Number(demand))} / ${fmt(Number(supply))} ${unit}</span></div><div class="progress-track"><div style="width:${clamp(Number(demand)/Math.max(1,Number(supply))*100,0,100)}%;background:${Number(demand)>Number(supply)?'#d88162':'#74a695'}"></div></div></div>`).join('')}</div><div class="quality-grid">${[[tr('Bildung','Education'),s.education],[tr('Gesundheit','Health'),s.health],[tr('Sicherheit','Safety'),s.safety],[tr('Verkehrsdichte','Traffic density'),s.traffic]].map(([label,value])=>`<div><span>${label}</span><b>${fmt(Number(value))} %</b></div>`).join('')}</div><p class="modal-note">${tr('Versorgte Bauzonen wachsen mit der Nachfrage. Parks und Stadtdienste erhöhen die Lebensqualität; Industrie kann Nachbargrundstücke belasten.','Serviced zones grow with demand. Parks and city services improve quality of life; industry can pollute nearby properties.')}</p>`,true);
 } else if(modal==='news'){
 modalShell(tr('Geschichten aus deiner Stadt.','Stories from your city.'),tr('STADTJOURNAL','CITY JOURNAL'),`<div class="event-list">${state.events.length?state.events.map(e=>`<article class="event ${e.type}"><span class="event-icon">${icon(e.type==='good'?'sprout':e.type==='warning'?'triangle-alert':'newspaper')}</span><div><small>${MONTHS()[e.month%12]} ${2000+Math.floor(e.month/12)}</small><h3>${escape(localizedEventTitle(e))}</h3><p>${escape(localizedEventMessage(e))}</p></div></article>`).join(''):`<p>${tr('Die erste Seite deiner Stadtgeschichte ist noch leer.','The first page of your city story is still empty.')}</p>`}</div>`);
 } else if(modal==='help'){
 modalShell(tr('Eine Stadt nach deinen Ideen.','A city shaped by your ideas.'),tr('WILLKOMMEN IN NEUSTADT','WELCOME TO NEUSTADT'),`<div class="help-cover"><img src="${import.meta.env.BASE_URL}assets/neustadt-cover.png" alt="${tr('Originales 3D-Stadtmotiv von Neustadt','Original 3D city artwork from Neustadt')}"/><div><span>${tr('DEIN KLEINES STÜCK ZUKUNFT','YOUR LITTLE PIECE OF THE FUTURE')}</span><h3>${tr('Baue. Verbinde.<br>Lass es wachsen.','Build. Connect.<br>Watch it grow.')}</h3></div></div><div class="help-steps">${[['01','route',tr('Verbinde deine Stadt','Connect your city'),tr('Ziehe Straßen über das Land. Große Gebäude benötigen ihre gesamte Baufläche; mit R kannst du sie drehen. Zonen brauchen einen Straßenanschluss, damit Menschen einziehen und Unternehmen entstehen.','Draw roads across the land. Large buildings need their entire footprint; press R to rotate them. Zones need road access so residents can move in and businesses can open.')],['02','house',tr('Gib Ideen einen Platz','Make room for ideas'),tr('Ziehe Wohn-, Gewerbe- und Industriezonen als Rechteck auf und lasse zum Bauen los. Rechtsklick oder Esc verwirft den Entwurf; das Werkzeug bleibt aktiv. Achte auf die Nachfrage: Gebäude entstehen von selbst.','Drag residential, commercial, and industrial zones as rectangles and release to build. Right-click or Esc cancels the draft and keeps your tool active. Watch demand: buildings appear on their own.')],['03','zap',tr('Sorge für das Wesentliche','Provide the essentials'),tr('Verbinde Kraftwerke über Stromleitungen mit deinen Baublöcken und Wasserwerke über unterirdische Rohre. Eine angrenzende Stromleitung versorgt den ganzen zusammenhängenden Block; Straßen trennen die Blöcke. Nur große Gebäude haben sichtbare Anschlusskabel, die nie über Straßen führen. Schulen, Kliniken, Polizei und Parks machen die Stadt lebenswert.','Connect power plants to your building blocks with power lines, and waterworks with underground pipes. A power line beside a connected block powers the entire block; roads separate blocks. Only large buildings have visible service cables, and those never cross roads. Schools, clinics, police, and parks improve quality of life.')],['04','chart-no-axes-combined',tr('Denke einen Schritt weiter','Plan one step ahead'),tr('Erfülle Aufträge, hole Belohnungen ab und entwickle deine Kleinstadt über die Großstadt zur Metropole. Im Stadtziel wartet eine lebenswerte Stadt für 25.000 Menschen.','Complete quests, collect rewards, and grow your small town into a city and then a metropolis. Your city goal is a great place to live for 25,000 people.')]].map(([num,ic,title,desc])=>`<article><span>${num}</span><div><h3>${icon(ic)} ${title}</h3><p>${desc}</p></div></article>`).join('')}</div><div class="keyboard-help"><span><kbd>${tr('Leertaste','Space')}</kbd> ${tr('Pause','Pause')}</span><span><kbd>Esc</kbd> ${tr('Bau abbrechen · Werkzeug behalten','Cancel construction · keep tool')}</span><span><kbd>V</kbd> ${tr('Auswählen','Select')}</span><span><kbd>1–5</kbd> ${tr('Bauen','Build')}</span><span><kbd>B</kbd> ${tr('Abreißen','Bulldoze')}</span><span><kbd>Q / E</kbd> ${tr('Drehen','Rotate')}</span><span><kbd>G</kbd> ${tr('Raster','Grid')}</span><span><kbd>${tr('Strg Z','Ctrl Z')}</kbd> ${tr('Rückgängig','Undo')}</span></div><button class="button primary full" id="start-playing">${tr('Meine Stadt gestalten','Create my city')} ${icon('arrow-right')}</button>`,true);$('#start-playing').onclick=closeModal;
 } else if(modal==='graphics'){
 modalShell(tr('Deine Stadt im besten Licht.','Your city in its best light.'),tr('GRAFIK & BELEUCHTUNG','GRAPHICS & LIGHTING'),`<div class="weather-options"><div><h3>${tr('Wetter & Oberflächen','Weather & surfaces')}</h3><p>${tr('Regen erzeugt nasse Straßen und Pfützen.','Rain creates wet roads and puddles.')}</p></div><button class="button ${state.settings.weather==='clear'?'primary':'secondary'}" data-weather="clear">${icon('sun')} ${tr('Klar','Clear')}</button><button class="button ${state.settings.weather==='rain'?'primary':'secondary'}" data-weather="rain">${icon('cloud-rain')} ${tr('Regen','Rain')}</button></div><div class="daylight-settings"><label for="building-lights">${tr('Gebäude- und Straßenbeleuchtung','Building and street lighting')}<input id="building-lights" type="checkbox" ${state.settings.buildingLights?'checked':''}/></label><small>${tr('Fenster, Laternen und ihre Lichtflächen einschalten. Auch direkt oben mit der Glühbirne oder Taste L.','Turn on windows, streetlights, and their pools of light. You can also use the lightbulb above or press L.')}</small><label for="day-cycle">${tr('Automatischer Tag-Nacht-Wechsel','Automatic day-night cycle')}<input id="day-cycle" type="checkbox" ${state.settings.dayNightCycle?'checked':''}/></label><small>${tr('Ein Tag dauert etwa vier Minuten bei laufender Stadt. Sonne und Schatten folgen der Uhrzeit.','A day lasts about four minutes while the city is running. The sun and shadows follow the time of day.')}</small><label for="day-hour">${tr('Tageszeit ','Time of day ')}<b id="day-hour-value">${Math.floor(state.settings.timeOfDay)}:00</b></label><input id="day-hour" type="range" min="0" max="23" step="1" value="${Math.floor(state.settings.timeOfDay)}"/></div><p class="modal-note">${tr('Wähle Auflösung, Schattendetails und Kantenglättung für deinen Rechner.','Choose the resolution, shadow detail, and antialiasing that suit your computer.')}</p><div class="graphics-presets">${([['performance',tr('Flüssig','Performance'),tr('Reduzierte Auflösung und kompakte Schatten','Lower resolution and simpler shadows')],['balanced',tr('Ausgewogen','Balanced'),tr('Weiche Schatten und geglättete Kanten','Soft shadows and smooth edges')],['ultra',tr('Sehr hoch','Ultra'),tr('Hohe Auflösung und feinere Schattendetails','High resolution and finer shadow detail')]] as const).map(([id,label,desc])=>`<button class="graphics-preset ${quality===id?'active':''}" data-quality="${id}">${icon(id==='performance'?'gauge':id==='balanced'?'sun':'sparkles')}<strong>${label}</strong><small>${desc}</small></button>`).join('')}</div>`);
 document.querySelectorAll<HTMLButtonElement>('[data-quality]').forEach(b=>b.onclick=()=>{quality=b.dataset.quality as typeof quality;scene.setGraphicsQuality(quality);safePreferenceSet('neustadt-quality',quality);renderModal();});$('#building-lights').onchange=e=>setBuildingLights((e.target as HTMLInputElement).checked);$('#day-cycle').onchange=e=>{clearDisasterUndo();state.settings.dayNightCycle=(e.target as HTMLInputElement).checked;scene.setDayNightCycle(state.settings.dayNightCycle);scheduleSave();};$('#day-hour').oninput=e=>{clearDisasterUndo();const hour=Number((e.target as HTMLInputElement).value);state.settings.timeOfDay=hour;state.settings.dayNightCycle=false;scene.setTimeOfDay(hour);scene.setDayNightCycle(false);$<HTMLInputElement>('#day-cycle').checked=false;$('#day-hour-value').textContent=`${hour}:00`;scheduleSave();};document.querySelectorAll<HTMLButtonElement>('[data-weather]').forEach(b=>b.onclick=()=>{state.settings.weather=b.dataset.weather as Weather;scene.setWeather(state.settings.weather);cityChanged();renderModal();});
 } else if(modal==='newcity'){
 modalShell(tr('Alles beginnt mit einer Idee.','It all starts with an idea.'),tr('NEUE STADT','NEW CITY'),`<p class="modal-note">${tr('Deine aktuelle Stadt bleibt erhalten, wenn du sie vorher exportierst. Beim Start wird der automatische Spielstand durch die neue Stadt ersetzt.','Export your current city first if you want to keep it. Starting a new city replaces the automatic save.')}</p><label class="form-label">${tr('Name der Stadt','City name')}<input id="new-name" type="text" maxlength="40" value="Lindenbucht"/></label><label class="form-label">${tr('Größe der Region','Region size')}<select id="new-size"><option value="64">${tr('64 × 64 · Kompakt','64 × 64 · Compact')}</option><option value="96">${tr('96 × 96 · Weitläufig','96 × 96 · Spacious')}</option><option value="128" selected>${tr('128 × 128 · Große Region (10× bisherige Fläche)','128 × 128 · Large region (10× the original area)')}</option></select></label><label class="form-label">${tr('Landschafts-Seed','Landscape seed')}<input id="new-seed" type="number" min="1" max="999999" value="${Math.floor(Math.random()*99999)+1}"/></label><div class="new-city-options"><button id="new-starter" class="button primary">${icon('building-2')} ${tr('Mit Starterstadt beginnen','Begin with a starter city')}</button><button id="new-empty" class="button secondary">${icon('sprout')} ${tr('Auf freiem Land beginnen','Begin on open land')}</button></div>`);const start=(empty:boolean)=>{const seed=clamp(Number($<HTMLInputElement>('#new-seed').value)||7341,1,999999);const name=$<HTMLInputElement>('#new-name').value.trim().slice(0,40)||'Lindenbucht';state=createCity(seed,empty,Number($<HTMLSelectElement>('#new-size').value));state.name=name;saveBlocked=false;recoveryRaw=null;clearUndo();selected=null;lastRank=getRank(state).id;victoryAnnounced=state.progression.victory;tickAccumulator=0;scene.exitDrive();syncScene(true);renderStats();renderTools();$('#inspector').classList.add('hidden');closeModal();save(false);toast(tr(`Willkommen in ${name}. Deine Geschichte beginnt.`,`Welcome to ${name}. Your story begins.`),'good');};$('#new-starter').onclick=()=>start(false);$('#new-empty').onclick=()=>start(true);
 } else if(modal==='disaster'){
 modalShell(tr('Wenn die Stadt dich braucht.','When your city needs you.'),tr('EXPERIMENTIERMODUS & KATASTROPHEN','SANDBOX & DISASTERS'),`<label class="disaster-switch"><span><strong>${tr('Katastrophenwerkzeuge aktivieren','Enable disaster tools')}</strong><small>${tr('Experimentiermodus: Ereignisse absichtlich auslösen.','Sandbox mode: trigger events deliberately.')}</small></span><input id="disaster-enabled" type="checkbox" ${state.settings.disastersEnabled?'checked':''}/></label><p class="modal-note">${tr('Diese Ereignisse beschädigen Gebäude und können Strom- und Wassernetze unterbrechen. Die letzte Katastrophe lässt sich bis zum nächsten Spielmonat rückgängig machen, solange du keine weiteren Änderungen an der Stadt vornimmst.','These events damage buildings and may disrupt power and water networks. You can undo the last disaster until the next game month, provided you make no further changes to the city.')}</p><div class="disaster-grid">${([['fire','flame',tr('Großbrand','Major fire'),tr('Feuer breitet sich aus. Versorgte Feuerwehren helfen.','Fire spreads. Supplied fire stations help fight it.')],['earthquake','activity',tr('Erdbeben','Earthquake'),tr('Gebäude und Straßen können einstürzen.','Buildings and roads may collapse.')],['flood','waves',tr('Hochwasser','Flood'),tr('Tiefliegende Küstenflächen und Anlagen werden beschädigt.','Low-lying coastal land and facilities are damaged.')],['storm','wind',tr('Schwerer Sturm','Severe storm'),tr('Windschäden treffen Gebäude und Stromleitungen.','High winds damage buildings and power lines.')]] as const).map(([id,ic,title,desc])=>`<button data-disaster="${id}" ${!state.settings.disastersEnabled?'disabled':''}>${icon(ic)}<strong>${title}</strong><span>${desc}</span></button>`).join('')}</div>`);
 $('#disaster-enabled').onchange=e=>{state.settings.disastersEnabled=(e.target as HTMLInputElement).checked;cityChanged();renderModal();};document.querySelectorAll<HTMLButtonElement>('[data-disaster]').forEach(b=>b.onclick=()=>{const previous=serializeCity(state);const result=triggerDisaster(state,b.dataset.disaster as DisasterKind);if(!result.ok)return toast(result.message,'warning');clearUndo();disasterUndo={raw:previous,month:state.month,revision:state.revision};syncScene();renderStats();scheduleSave();closeModal();toast(result.message,'warning');});
 } else {
 modalShell(tr('Deine Stadt. Dein Spiel.','Your city. Your game.'),tr('STADTMENÜ','CITY MENU'),` ${recoveryRaw?`<div class="storage-warning">${tr('Der nicht lesbare Originalspielstand wird nicht überschrieben.','The unreadable original save will not be overwritten.')} <button id="download-recovery" class="text-link">${tr('Originaldatei sichern','Back up original file')}</button></div>`:''}<div class="menu-city"><img src="${import.meta.env.BASE_URL}assets/neustadt-cover.png" alt="${tr('Neustadt Küstenstadt','Neustadt coastal city')}"/><div><strong>${escape(state.name)}</strong><span>${fmt(state.stats.population)} ${tr('Einwohner','residents')} · ${MONTHS()[state.month%12]} ${2000+Math.floor(state.month/12)}</span></div></div><label class="form-label">${tr('Stadtname','City name')}<div class="rename-row"><input id="rename-input" value="${escape(state.name)}" maxlength="40"/><button class="button secondary" id="rename-btn">${tr('Ändern','Rename')}</button></div></label><div class="menu-grid">${[['menu-save','save',tr('Stadt speichern','Save city'),tr('Lokal in diesem Browser','Locally in this browser')],['menu-export','download',tr('Spielstand exportieren','Export save'),tr('Als JSON-Datei sichern','Save as a JSON file')],['menu-import','upload',tr('Spielstand importieren','Import save'),tr('Gesicherte Stadt fortsetzen','Continue a saved city')],['menu-new','sprout',tr('Neue Stadt','New city'),tr('Eine neue Geschichte beginnen','Begin a new story')],['menu-photo','camera',tr('Stadt fotografieren','Take a photo'),tr('Deine Perspektive als PNG','Export your view as a PNG')],['menu-disaster','flame',tr('Katastrophen','Disasters'),tr('Experimentiermodus aktivieren','Enable sandbox events')],['menu-progress','flag',tr('Stadtentwicklung','City development'),tr('3 Stufen · Aufträge · Challenges','3 levels · Quests · Challenges')],['menu-news','newspaper',tr('Stadtjournal','City journal'),tr('Ereignisse und Meldungen lesen','Read events and city news')],['menu-camera','hand',tr('Kamera & Bewohner','Camera & residents'),tr('Navigation und Greifen','Navigation and picking up residents')]].map(([id,ic,title,sub])=>`<button id="${id}">${icon(ic)}<span><strong>${title}</strong><small>${sub}</small></span>${icon('chevron-right')}</button>`).join('')}</div><div class="menu-footer"><span>${tr('NEUSTADT · REGIONEN & STADTLEBEN · V2','NEUSTADT · REGIONS & CITY LIFE · V2')}</span><button id="menu-help" class="text-link">${tr('Spielanleitung','How to play')} ${icon('arrow-up-right')}</button></div>`);
 $('#download-recovery')?.addEventListener('click',()=>{if(recoveryRaw)download(new Blob([recoveryRaw],{type:'application/json'}),tr('neustadt-original-sicherung.json','neustadt-original-backup.json'));});$('#rename-btn').onclick=()=>{const name=$<HTMLInputElement>('#rename-input').value.trim();if(name){state.name=name;cityChanged();save(false);toast(tr('Deine Stadt hat einen neuen Namen.','Your city has a new name.'),'good');renderModal();}};$('#menu-save').onclick=()=>save();$('#menu-export').onclick=()=>download(new Blob([serializeCity(state)],{type:'application/json'}),`${state.name.toLowerCase().replace(/[^a-z0-9äöüß_-]/g,'-')}-${tr('spielstand','save')}.json`);$('#menu-import').onclick=()=>{$<HTMLInputElement>('#import-file').click();};$('#menu-new').onclick=()=>openModal('newcity');$('#menu-photo').onclick=()=>{const a=document.createElement('a');a.href=scene.screenshot();a.download=tr('neustadt-stadtansicht.png','neustadt-city-view.png');a.click();toast(tr('Deine Stadtansicht wurde als PNG exportiert.','Your city view has been exported as a PNG.'),'good');};$('#menu-disaster').onclick=()=>openModal('disaster');$('#menu-help').onclick=()=>openModal('help');$('#menu-progress').onclick=()=>openModal('progression');$('#menu-camera').onclick=()=>openModal('camera');$('#menu-news').onclick=()=>openModal('news');
 }
}
function historyChart(){const points=state.history.slice(-36);if(points.length<2)return `<div class="chart-empty">${tr('Die erste Statistik entsteht, sobald ein Spielmonat vergangen ist.','The first statistics will appear after one game month.')}</div>`;const max=Math.max(...points.map(p=>p.population),1)*1.15;const w=660,h=150,pad=30;const coords=points.map((p,i)=>`${pad+i*(w-pad*2)/(points.length-1)},${h-pad-p.population/max*(h-pad*2)}`);return `<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${tr(`Bevölkerungsentwicklung von ${fmt(points[0].population)} auf ${fmt(points.at(-1)!.population)} Einwohner`,`Population history from ${fmt(points[0].population)} to ${fmt(points.at(-1)!.population)} residents`)}"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#7fac97" stop-opacity=".35"/><stop offset="100%" stop-color="#7fac97" stop-opacity="0"/></linearGradient></defs>${[.25,.5,.75].map(v=>`<line x1="${pad}" y1="${h-pad-v*(h-pad*2)}" x2="${w-pad}" y2="${h-pad-v*(h-pad*2)}" stroke="#e7eae2" stroke-dasharray="3 5"/>`).join('')}<path d="M ${pad},${h-pad} L ${coords.join(' L ')} L ${w-pad},${h-pad} Z" fill="url(#chart-fill)"/><polyline points="${coords.join(' ')}" fill="none" stroke="#55856f" stroke-width="2.5" stroke-linejoin="round"/><text x="${pad}" y="${h-4}" fill="#8a958b" font-size="10">${MONTHS()[points[0].month%12]} ${2000+Math.floor(points[0].month/12)}</text><text x="${w-pad}" y="${h-4}" text-anchor="end" fill="#8a958b" font-size="10">${MONTHS()[points.at(-1)!.month%12]} ${2000+Math.floor(points.at(-1)!.month/12)}</text></svg>`;}

function rerenderKeepingFocus(id:string){const value=$<HTMLInputElement>('#'+id)?.value;renderModal();const el=$<HTMLInputElement>('#'+id);if(el){if(value!==undefined)el.value=value;el.focus({preventScroll:true});}}

function download(blob:Blob,name:string){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(tr("Spielstand exportiert.", "City save exported."),'good');}
function wireEvents(includeGlobal=true){
 wireLanguageControls();
 document.querySelectorAll<HTMLButtonElement>('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category!;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));renderTools();});
 document.querySelectorAll<HTMLButtonElement>('[data-speed]').forEach(b=>b.onclick=()=>{state.speed=Number(b.dataset.speed) as CityState['speed'];renderStats();});document.querySelectorAll<HTMLButtonElement>('[data-brush]').forEach(b=>b.onclick=event=>{brush=Number(b.dataset.brush);scene.setTool(tool,brush,buildingRotation);document.querySelectorAll('[data-brush]').forEach(x=>x.classList.toggle('active',x===b));focusWorldAfterPointer(event);});
 $('#vehicle-hotspot').onmouseleave=()=>{$('#vehicle-hotspot').classList.add('hidden');};$('#vehicle-hotspot').onclick=()=>{if(hoveredVehicle!==null&&scene.enterDrive(hoveredVehicle)){$('#vehicle-hotspot').classList.add('hidden');}};$('#exit-drive').onclick=()=>scene.exitDrive();$('#goals-btn').onclick=()=>openModal('progression');$('#overview-btn').onclick=()=>scene.overview();$('#pan-btn').onclick=event=>{selectTool('pan');focusWorldAfterPointer(event);};$('#camera-help').onclick=()=>openModal('camera');$('#rotate-building').onclick=event=>{buildingRotation=((buildingRotation+1)%4) as 0|1|2|3;scene.setTool(tool,brush,buildingRotation);focusWorldAfterPointer(event);};$('#graphics-btn').onclick=()=>openModal('graphics');$('#save-btn').onclick=()=>save();$('#undo-btn').onclick=undo;$('#menu-btn').onclick=()=>openModal('menu');$('#city-name').onclick=()=>openModal('menu');$('#budget-stat').onclick=()=>openModal('budget');$('#population-stat').onclick=()=>openModal('reports');$('#happiness-stat').onclick=()=>openModal('reports');$('#help-btn')?.addEventListener('click',()=>openModal('help'));$('#help-shortcut').onclick=()=>openModal('help');$('#brand-help').onclick=e=>{e.preventDefault();openModal('help');};$('#news-btn').onclick=()=>openModal('news');$('#advisor-close')?.addEventListener('click',()=>{minimizeAdvisor=true;$('#advisor').classList.add('hidden');});
 $('#building-lights-btn').onclick=()=>setBuildingLights(!state.settings.buildingLights);$('#zoom-in').onclick=()=>scene.zoom(1);$('#zoom-out').onclick=()=>scene.zoom(-1);$('#rotate-left').onclick=()=>scene.rotate(-1);$('#rotate-right').onclick=()=>scene.rotate(1);$('#camera-home').onclick=()=>scene.resetCamera();$('#overlay-select').onchange=e=>setOverlay((e.target as HTMLSelectElement).value as Overlay);$('#grid-btn').onclick=()=>{grid=!grid;scene.setGrid(grid);$('#grid-btn').classList.toggle('active',grid);$('#grid-btn').setAttribute('aria-pressed',String(grid));};$('#night-btn').onclick=()=>{clearDisasterUndo();night=scene.getTimeOfDay()>=6&&scene.getTimeOfDay()<19;state.settings.timeOfDay=night?21:14;state.settings.dayNightCycle=false;scene.setTimeOfDay(state.settings.timeOfDay);scene.setDayNightCycle(false);$('#night-btn').innerHTML=icon(night?'moon':'sun');$('#night-btn').classList.toggle('active',night);$('#night-btn').setAttribute('aria-pressed',String(night));refreshIcons($('#night-btn'));scheduleSave();};
 $('#minimap').onclick=e=>{const rect=$('#minimap').getBoundingClientRect();scene.focus(Math.floor((e.clientX-rect.left)/rect.width*state.size),Math.floor((e.clientY-rect.top)/rect.height*state.size));};
 $('#import-file').onchange=async e=>{const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.size>12_000_000)throw Error(tr("Datei ist zu groß.", "The file is too large."));const imported=deserializeCity(await file.text());state=imported.size===40?expandCity(imported,128):imported;state.speed=0;saveBlocked=false;recoveryRaw=null;clearUndo();selected=null;lastRank=getRank(state).id;victoryAnnounced=state.progression.victory;tickAccumulator=0;scene.exitDrive();syncScene(true);renderStats();renderTools();$('#inspector').classList.add('hidden');closeModal();save(false);toast(tr(`${state.name} erfolgreich geladen.`,`${state.name} loaded successfully.`),'good');}catch(err){toast(tr(`Spielstand konnte nicht geladen werden: ${err instanceof Error?err.message:'Ungültige Datei'}`,`Could not load the save: ${err instanceof Error?err.message:'Invalid file'}`),'warning');}(e.target as HTMLInputElement).value='';};
 if(!includeGlobal)return;
 $('#world').addEventListener('pointerdown',()=>{if(!modal)$('#world').focus({preventScroll:true});},true);
 window.addEventListener('keydown',e=>{
  const target=e.target instanceof Element?e.target:null;
  const editable=!!target?.closest('input,select,textarea,[contenteditable="true"]');
  const control=!!target?.closest('button,a[href],input,select,textarea,[role="button"],[contenteditable="true"]');
  const key=e.key.toLowerCase(),command=e.ctrlKey||e.metaKey;
  if(modal&&e.key==='Tab'){
   const focusable=modalFocusables(),current=focusable.indexOf(document.activeElement as HTMLElement);
   if(e.shiftKey&&current<=0){e.preventDefault();focusable.at(-1)?.focus();}
   else if(!e.shiftKey&&(current<0||current===focusable.length-1)){e.preventDefault();focusable[0]?.focus();}
   return;
  }
  if(command&&!e.altKey&&!e.shiftKey&&key==='s'){e.preventDefault();if(!e.repeat)void save();return;}
  if(e.key==='Escape'){
   if(e.repeat)return;e.preventDefault();
   if(modal){closeModal();return;}
   if(driving){scene.exitDrive();return;}
   scene.cancelInteraction();$('#inspector').classList.add('hidden');selected=null;return;
  }
  if(command&&!e.altKey&&!e.shiftKey&&key==='z'&&!editable&&!modal&&!driving){e.preventDefault();if(!e.repeat)undo();return;}
  if(control||modal||driving||command||e.altKey||e.shiftKey||e.repeat)return;
  if(e.code==='Space'){e.preventDefault();state.speed=state.speed?0:1;renderStats();return;}
  if(key==='r'&&TOOL_DEFS[tool]?.footprint){e.preventDefault();$('#rotate-building').click();return;}
  const keys:Record<string,Tool>={'m':'pan','c':'citizen','1':'road','2':'residential','3':'commercial','4':'industrial','5':'park','b':'bulldoze','v':'inspect'};
  if(keys[key]){e.preventDefault();category='favorites';document.querySelectorAll<HTMLElement>('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===category));selectTool(keys[key]);return;}
  if(key==='q')scene.rotate(-1);if(key==='e')scene.rotate(1);
  if(key==='g')$('#grid-btn').click();if(key==='n')$('#night-btn').click();if(key==='l')$('#building-lights-btn').click();if(key==='h')openModal('help');
 });
 window.addEventListener('resize',positionBuildPreview);
 window.visualViewport?.addEventListener('resize',positionBuildPreview);
 window.addEventListener('beforeunload',()=>save(false));document.addEventListener('visibilitychange',()=>{if(document.hidden)save(false);previousTime=performance.now();});
}
function loop(time:number){const delta=Math.min((time-previousTime)/1000,.25);previousTime=time;fps=1/Math.max(.001,delta);frameCount++;if(!document.hidden&&!modal&&state.speed>0){tickAccumulator+=delta*[0,1,2,3][state.speed];if(tickAccumulator>=5){tickAccumulator-=5;clearDisasterUndo();tick(state);syncScene();renderStats();renderInspector();const rank=getRank(state);if(rank.id>lastRank){lastRank=rank.id;renderTools();toast(tr(`Ausbaustufe ${rank.id+1}: ${rank.name}! Neue Gebäude sind freigeschaltet.`,`City tier ${rank.id+1}: ${rank.name}! New buildings unlocked.`),'good');}if(state.progression.victory&&!victoryAnnounced){victoryAnnounced=true;progressionTab='goal';openModal('progression');}if(state.events[0]?.id!==lastEvent){lastEvent=state.events[0]?.id??0;const latest=state.events[0];if(latest?.type==='warning')toast(localizedEventMessage(latest),'warning');}}}if(frameCount%30===0&&scene)renderDayClock();if(!savePending&&Date.now()>nextAutosave)void save(false);requestAnimationFrame(loop);}
async function start(){
 try{
  const load=await loadSavedCity();
  if(load.error){loadError=load.error;saveBlocked=true;}
  if(load.raw){try{const city=deserializeCity(load.raw);if(load.source==='legacy'){try{await backupLegacy(load.raw);}catch{loadNotice=tr("Die alte Sicherung bleibt erhalten. Die Stadt wird geladen.", "Your old backup is preserved. Loading the city.");}}state=city.size===40?expandCity(city,128):city;state.speed=0;saved=true;if(city.size===40)loadNotice=tr(`${state.name} wurde mit deiner bestehenden Bebauung auf ${state.size} × ${state.size} Felder erweitert.`,`${state.name} has been expanded to ${state.size} × ${state.size} tiles, preserving your existing buildings.`);}catch(error){saveBlocked=true;recoveryRaw=load.raw;loadError=tr(`Der bisherige Spielstand bleibt geschützt: ${error instanceof Error?error.message:'Laden fehlgeschlagen'}`,`Your previous save remains protected: ${error instanceof Error?error.message:'Loading failed'}`);}}
  const preference=safePreferenceGet('neustadt-quality');if(['performance','balanced','ultra'].includes(preference??''))quality=preference as typeof quality;
  lastRank=getRank(state).id;victoryAnnounced=state.progression.victory;syncScene();renderTools();renderStats();wireEvents();refreshIcons();started=true;$('#loading-screen').classList.add('loaded');setTimeout(()=>$('#loading-screen')?.remove(),650);
  if(saveBlocked)$('#autosave-status').textContent=tr("Alter Spielstand geschützt · Export möglich", "Old save protected · export available");if(loadError)toast(loadError,'warning');else if(loadNotice)toast(loadNotice,'good');else if(saved)toast(tr("Willkommen zurück. Deine Stadt wurde geladen.", "Welcome back. Your city has been loaded."),'good');
  if(!saveBlocked)scheduleSave();requestAnimationFrame(loop);
  Object.defineProperty(window,'neustadtDebug',{get:()=>({state:structuredClone(state),locale:getLocale(),tool,overlay,night,grid,quality,driving,rotation:buildingRotation,renderStatus:{mode:"realtime",status:tr("Echtzeit", "Realtime")},preview:lastPreview,interactionTargets:scene.getInteractionTargets?.(),diagnostics:scene.getDiagnostics?.(),drivingStatus:scene.getDrivingStatus(),fps:Math.round(fps),frames:frameCount,buildCount,undoCount:constructionHistory.length+(disasterUndo?1:0),saveBlocked,savePending,saveFailed})});
 }catch(error){$('#loading-screen').innerHTML=`<h2>${tr('Die Stadt konnte nicht gestartet werden.','The city could not be started.')}</h2><p>${escape(error instanceof Error?error.message:tr("Unbekannter Fehler", "Unknown error"))}</p><p>${tr('Bitte verwende einen Browser mit aktivierter WebGL-Grafik.','Please use a browser with WebGL graphics enabled.')}</p>`;console.error(error);}
}
start();
